---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Stepper: A multi-step setup with a progress track that fills as you go.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change stepper.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './stepper.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="stepper" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="stx">
  <div class="stx-track"></div>
  <div class="stx-vp"><div class="stx-body"></div></div>
  <div class="stx-f"><button class="pill ghost sm stx-bk">Back</button><button class="pill primary sm stx-nx">Continue</button></div>
</div>
  </Fragment></div>
</div>
<script>
  import './stepper.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Stepper ---------- */
/* the agent walks you through setup in the chat: no container; with .panel it becomes a card */
.stx{padding:var(--dm-s-4) 0;display:flex;flex-direction:column;gap:var(--dm-s-4)}
.stx.panel{padding:var(--dm-s-4)}
.stx-track{display:flex;align-items:center;gap:0}
.stx-st{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12.5px;color:var(--dm-muted);white-space:nowrap;transition:color .3s}
.stx-st .n{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-size:11.5px;font-weight:500;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-muted);transition:background .35s var(--dm-ease),box-shadow .35s,color .35s;flex:none}
.stx-st.on{color:var(--dm-fg)}
.stx-st.on .n{box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent)),0 0 0 4px var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.stx-st.done{color:var(--dm-fg2);cursor:pointer}
.stx-st.done .n{background:var(--dm-accent);box-shadow:none;color:var(--dm-on-accent)}
.stx-ln{flex:1;height:2px;margin:0 10px;border-radius:1px;background:var(--dm-line);position:relative;overflow:hidden;min-width:16px}
.stx-ln i{position:absolute;inset:0;background:var(--dm-accent-mark,var(--dm-accent));transform:scaleX(0);transform-origin:left;transition:transform .5s var(--dm-ease)}
.stx-ln.full i{transform:none}
@media (max-width:520px){.stx-st .lb{display:none}.stx-st.on .lb{display:inline}}
/* each step sits in the middle, the same distance from the track above and the buttons below */
.stx-vp{overflow-x:clip;overflow-y:visible;min-height:150px;display:flex;flex-direction:column;justify-content:center}
.stx-body{display:flex;flex-direction:column;gap:10px}
.stx-body.inr{animation:stxr .45s var(--dm-ease) both}.stx-body.inl{animation:stxl .45s var(--dm-ease) both}
@keyframes stxr{from{opacity:0;transform:translateX(24px);filter:blur(4px)}}
@keyframes stxl{from{opacity:0;transform:translateX(-24px);filter:blur(4px)}}
.stx-body h4{margin:0;font-size:14px;font-weight:500}
.stx-body p{margin:0;font-size:12.5px;color:var(--dm-muted)}
.stx-opts{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--dm-s-2)}
@media (max-width:520px){.stx-opts{grid-template-columns:1fr}}
.stx-o{padding:var(--dm-s-3);border-radius:var(--dm-r-in);background:var(--dm-chip);text-align:left;font-size:13px;display:flex;flex-direction:column;gap:var(--dm-s-1);transition:background .2s,box-shadow .25s}
.stx-o span{font-size:11.5px;color:var(--dm-muted)}
@media (hover:hover) and (pointer:fine){.stx-o:hover{background:var(--dm-hover)}}
/* the options fill the sliding view, which would cut an outside ring: theirs is drawn inside */
.stx-o:focus-visible{outline-offset:-2px}
/* the options are grey tiles with no edge; the picked one turns white with a dimmed grey edge */
.stx-o.on{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),0 1px 2px rgba(0,0,0,.04)}
@media (hover:hover) and (pointer:fine){.stx-o.on:hover{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-line) 50%,transparent),0 1px 2px rgba(0,0,0,.04)}}
.stx-f{display:flex;justify-content:space-between}
/* once it's done there is nothing to go back to: Start over sits alone in the middle */
.stx.fin .stx-f{justify-content:center}
.stx.fin .stx-bk{display:none}
/* finished: the track has done its job, so only the success shows, centred in the height the steps had */
.stx.fin .stx-track{display:none}
.stx.fin .stx-vp{min-height:0}.stx.fin .stx-dn{padding:0 0 var(--dm-s-2)}
.stx-bk[disabled]{visibility:hidden}
.stx-dn{display:flex;flex-direction:column;align-items:center;gap:6px;padding:18px 0;text-align:center;font-size:13px}
.stx-dn>b{font-size:14px;font-weight:500}
/* finished: the check pops and draws itself, a soft ring spreads from it, and a little confetti bursts out once */
.stx-ok{position:relative;width:44px;height:44px;margin-bottom:6px}
.stx-ok svg{display:block;width:44px;height:44px;overflow:visible}
.stx-ok .c{fill:var(--dm-accent-mark,var(--dm-accent));transform-origin:center;transform-box:fill-box}
.stx-ok .k{fill:none;stroke:var(--dm-on-accent);stroke-width:3;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:24}
.stx-ok::after{content:"";position:absolute;inset:0;border-radius:50%;pointer-events:none}
.stx-dn.go .stx-ok .c{animation:stxpop .6s var(--dm-ease) both}
.stx-dn.go .stx-ok .k{animation:stxdraw .42s var(--dm-ease) .26s both}
.stx-dn.go .stx-ok::after{animation:stxring 1.2s var(--dm-ease) .18s}
@keyframes stxpop{from{transform:scale(.3);opacity:0}60%{transform:scale(1.08);opacity:1}to{transform:none;opacity:1}}
@keyframes stxdraw{from{stroke-dashoffset:24}to{stroke-dashoffset:0}}
@keyframes stxring{from{box-shadow:0 0 0 0 color-mix(in srgb,var(--dm-fg) 16%,transparent)}to{box-shadow:0 0 0 20px color-mix(in srgb,var(--dm-fg) 0%,transparent)}}
.stx-conf{position:absolute;left:50%;top:50%;width:0;height:0;pointer-events:none}
.stx-conf i{position:absolute;left:0;top:0;border-radius:2px;opacity:0}
.stx-conf i.d{border-radius:50%}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, enter, hold, release } from '../core/core.js';
DM.def('stepper', (r, c) => {
  const S = [
    ['Workspace','Name your workspace','This is what your team will see.',[['Studio','Small team'],['Agency','Many clients'],['In-house','One product']]],
    ['Agent','How should the agent work?','You can change this any time.',[['Ask first','Safest'],['Balanced','Recommended'],['Autopilot','Fastest']]],
    ['Connect','Where do your designs live?','Pick one to start.',[['Figma','Frames and tokens'],['GitHub','Code and PRs'],['Both','Full loop']]]
  ];
  const stx = $('.stx', r), track = $('.stx-track', r), body = $('.stx-body', r), bk = $('.stx-bk', r), nx = $('.stx-nx', r);
  let cur = 0, pick = [0, 1, 2];
  track.innerHTML = S.map((s, i) => `<div class="stx-st" data-i="${i}"><span class="n">${i + 1}</span><span class="lb">${s[0]}</span></div>` + (i < S.length - 1 ? '<div class="stx-ln"><i></i></div>' : '')).join('');
  const sts = $$('.stx-st', track), lns = $$('.stx-ln', track);
  function show(i, dir){
    cur = i; sts.forEach((s, j) => { s.classList.toggle('on', j === i); s.classList.toggle('done', j < i); $('.n', s).innerHTML = j < i ? I('check','xs') : j + 1; });
    lns.forEach((l, j) => l.classList.toggle('full', j < i));
    if (i >= S.length){
      if (!stx.classList.contains('fin')) hold(stx);
      body.innerHTML = `<div class="stx-dn"><span class="stx-ok"><svg viewBox="0 0 44 44" aria-hidden="true"><circle class="c" cx="22" cy="22" r="20"/><path class="k" d="M14 22.5l5.5 5.5L30.5 16.5"/></svg></span><b>You're set up</b><span class="muted">${S.map((s, k) => s[3][pick[k]][0]).join(' · ')}</span></div>`;
      bk.disabled = true; nx.textContent = 'Start over'; stx.classList.add('fin');
      // arriving here from Finish is the moment to celebrate; the screen itself doesn't slide
      if (dir > 0){ const dn = $('.stx-dn', body); dn.classList.add('go'); enter($('b', dn), 260); enter($('.muted', dn), 340); burst($('.stx-ok', dn)); }
      return;
    }
    else { if (stx.classList.contains('fin')){ stx.classList.remove('fin'); release(stx); } const s = S[i]; body.innerHTML = `<h4>${s[1]}</h4><p>${s[2]}</p><div class="stx-opts">${s[3].map((o, k) => `<button class="stx-o${pick[i] === k ? ' on' : ''}" data-k="${k}"><b style="font-weight:500">${o[0]}</b><span>${o[1]}</span></button>`).join('')}</div>`;
      $$('.stx-o', body).forEach(b => b.onclick = () => { pick[i] = +b.dataset.k; $$('.stx-o', body).forEach(x => x.classList.toggle('on', x === b)); });
      bk.disabled = i === 0; nx.textContent = i === S.length - 1 ? 'Finish' : 'Continue'; }
    if (dir){ body.classList.remove('inr','inl'); void body.offsetWidth; body.classList.add(dir > 0 ? 'inr' : 'inl'); }
  }
  // a short burst of confetti from the check, in the accent and a few brand colours, falling as it fades
  function burst(at){
    if (REDUCE) return;
    const bp = getComputedStyle(r).getPropertyValue('--dm-motion').trim() === 'bp';
    const box = document.createElement('span'); box.className = 'stx-conf'; at.appendChild(box);
    const COL = ['var(--dm-accent-mark,var(--dm-accent))', 'var(--dm-ok)', 'var(--dm-c2)', 'var(--dm-c4)', 'var(--dm-c5)', 'var(--dm-c6)'], N = 22;
    for (let k = 0; k < N; k++){
      const p = document.createElement('i'), round = k % 3 === 0, a = -Math.PI / 2 + (k / (N - 1) - .5) * Math.PI * 1.5 + Math.sin(k * 7.3) * .18;
      const d = 46 + (k * 37 % 30), w = round ? 5 : 3 + k % 2, h = round ? 5 : 7 + k % 3;
      p.className = round ? 'd' : ''; p.style.width = w + 'px'; p.style.height = h + 'px'; p.style.marginLeft = -w / 2 + 'px'; p.style.marginTop = -h / 2 + 'px'; p.style.background = COL[k % COL.length];
      box.appendChild(p);
      const x = Math.cos(a) * d, y = Math.sin(a) * d, r0 = k * 47 % 180, spin = (k % 2 ? 1 : -1) * (180 + k * 23 % 200), ms = (bp ? 760 : 1150) + k * 13 % 220;
      p.animate([
        { opacity:1, transform:`translate(0,0) rotate(${r0}deg) scale(.6)` },
        { opacity:1, transform:`translate(${x}px,${y}px) rotate(${r0 + spin * .5}deg) scale(1)`, offset:.42 },
        { opacity:0, transform:`translate(${x * 1.18}px,${y + 46}px) rotate(${r0 + spin}deg) scale(.9)` }
      ], { duration:ms, delay:120 + k % 4 * 18, easing:bp ? 'cubic-bezier(.65,0,.25,1)' : 'cubic-bezier(.16,1,.3,1)', fill:'both' });
    }
    c.later(1700, () => box.remove());
  }
  nx.onclick = () => cur >= S.length ? show(0, -1) : show(cur + 1, 1);
  bk.onclick = () => show(Math.max(0, cur - 1), -1);
  sts.forEach((s, i) => s.onclick = () => { if (i < cur) show(i, -1); });
  show(0);
});
